# 6-ingilizce-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">HAVE GOT / HAS GOT — EXPRESSING POSSESSION</text><rect x="20" y="50" width="230" height="195" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/><text x="135" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Affirmative (+)</text><text x="135" y="102" text-anchor="middle" font-size="12" fill="#14532d">I / You / We / They</text><text x="135" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">have got (\'ve got)</text><text x="135" y="148" text-anchor="middle" font-size="12" fill="#14532d">He / She / It</text><text x="135" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">has got (\'s got)</text><text x="135" y="200" text-anchor="middle" font-size="11" fill="#334155">I\'ve got a new swimsuit.</text><text x="135" y="220" text-anchor="middle" font-size="11" fill="#334155">She\'s got a lovely necklace.</text><rect x="265" y="50" width="230" height="195" rx="10" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/><text x="380" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">Negative (−)</text><text x="380" y="102" text-anchor="middle" font-size="12" fill="#7f1d1d">I / You / We / They</text><text x="380" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">haven\'t got</text><text x="380" y="148" text-anchor="middle" font-size="12" fill="#7f1d1d">He / She / It</text><text x="380" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">hasn\'t got</text><text x="380" y="200" text-anchor="middle" font-size="11" fill="#334155">We haven\'t got tights.</text><text x="380" y="220" text-anchor="middle" font-size="11" fill="#334155">He hasn\'t got a wallet.</text><rect x="510" y="50" width="230" height="195" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/><text x="625" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Question (?)</text><text x="625" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Have you got a purse?</text><text x="625" y="122" text-anchor="middle" font-size="11" fill="#334155">Yes, I have. / No, I haven\'t.</text><text x="625" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Has she got a chain?</text><text x="625" y="176" text-anchor="middle" font-size="11" fill="#334155">Yes, she has. / No, she hasn\'t.</text><text x="625" y="210" text-anchor="middle" font-size="11" fill="#334155">Has your coat got a pocket?</text><text x="625" y="228" text-anchor="middle" font-size="11" fill="#334155">Yes, it has.</text><rect x="20" y="257" width="720" height="32" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1"/><text x="380" y="278" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Kısa cevapta got kullanılmaz: Yes, I have. (Yes, I have got. değil!)</text></svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">LOOK, LOOK LIKE AND SEEM</text><rect x="20" y="50" width="230" height="190" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/><text x="135" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">LOOK + adjective</text><text x="135" y="96" text-anchor="middle" font-size="11" fill="#475569">(... görünmek)</text><text x="135" y="126" text-anchor="middle" font-size="12" fill="#1e3a8a">You look lovely.</text><text x="135" y="150" text-anchor="middle" font-size="12" fill="#1e3a8a">Ali looks tired.</text><text x="135" y="174" text-anchor="middle" font-size="12" fill="#1e3a8a">She looks happy today.</text><text x="135" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">look + happy / tired / lovely</text><rect x="265" y="50" width="230" height="190" rx="10" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/><text x="380" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">LOOK LIKE + noun</text><text x="380" y="96" text-anchor="middle" font-size="11" fill="#475569">(-e benzemek)</text><text x="380" y="126" text-anchor="middle" font-size="12" fill="#9d174d">Elif looks like her mother.</text><text x="380" y="150" text-anchor="middle" font-size="12" fill="#9d174d">He looks like a footballer.</text><text x="380" y="174" text-anchor="middle" font-size="12" fill="#9d174d">It looks like a gold chain.</text><text x="380" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">look like + person / thing</text><rect x="510" y="50" width="230" height="190" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/><text x="625" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">SEEM + adjective</text><text x="625" y="96" text-anchor="middle" font-size="11" fill="#475569">(... gibi görünmek, izlenim)</text><text x="625" y="126" text-anchor="middle" font-size="12" fill="#14532d">The new girl seems shy.</text><text x="625" y="150" text-anchor="middle" font-size="12" fill="#14532d">Our coach seems serious.</text><text x="625" y="174" text-anchor="middle" font-size="12" fill="#14532d">You seem focused today.</text><text x="625" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">first impression (ilk izlenim)</text><rect x="20" y="254" width="720" height="34" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1"/><text x="380" y="276" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Görünüşe aldanma: She seems serious, but she is very caring!</text></svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">PERSONALITY &amp; CHARACTER — NEW WORDS</text><rect x="20" y="48" width="400" height="170" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/><text x="220" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Positive Traits (Olumlu)</text><text x="220" y="98" text-anchor="middle" font-size="12" fill="#14532d">brilliant (parlak zekâlı) · clever (zeki)</text><text x="220" y="120" text-anchor="middle" font-size="12" fill="#14532d">caring (şefkatli) · patient (sabırlı) · polite (kibar)</text><text x="220" y="142" text-anchor="middle" font-size="12" fill="#14532d">independent (bağımsız) · helpful (yardımsever)</text><text x="220" y="164" text-anchor="middle" font-size="12" fill="#14532d">organised (planlı) · tidy (derli toplu)</text><text x="220" y="186" text-anchor="middle" font-size="12" fill="#14532d">focused (odaklanmış) · social · serious · simple</text><text x="220" y="206" text-anchor="middle" font-size="11" fill="#475569">sense of humour = mizah anlayışı</text><rect x="440" y="48" width="300" height="170" rx="10" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/><text x="590" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">Negative Traits (Olumsuz)</text><text x="590" y="102" text-anchor="middle" font-size="12" fill="#7f1d1d">lazy (tembel)</text><text x="590" y="126" text-anchor="middle" font-size="12" fill="#7f1d1d">rude (kaba)</text><text x="590" y="150" text-anchor="middle" font-size="12" fill="#7f1d1d">weak (zayıf, güçsüz)</text><text x="590" y="174" text-anchor="middle" font-size="12" fill="#7f1d1d">crazy (çılgın, deli dolu)</text><text x="590" y="202" text-anchor="middle" font-size="11" fill="#475569">polite ↔ rude · strong ↔ weak</text><rect x="20" y="230" width="720" height="58" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/><text x="380" y="253" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Adjective → Adverb: happy → happily · sad → sadly</text><text x="380" y="276" text-anchor="middle" font-size="12" fill="#1e3a8a">She is happy. → She smiles happily.   He is sad. → He looks at his pocket sadly.</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">SUPERLATIVES — WHO IS THE TALLEST?</text><line x1="40" y1="250" x2="400" y2="250" stroke="#64748b" stroke-width="2"/><rect x="70" y="140" width="70" height="110" rx="6" fill="#93c5fd"/><text x="105" y="132" text-anchor="middle" font-size="12" fill="#1e293b">150 cm</text><text x="105" y="268" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Ece</text><text x="105" y="284" text-anchor="middle" font-size="11" fill="#b91c1c">the shortest</text><rect x="185" y="110" width="70" height="140" rx="6" fill="#60a5fa"/><text x="220" y="102" text-anchor="middle" font-size="12" fill="#1e293b">158 cm</text><text x="220" y="268" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Defne</text><text x="220" y="284" text-anchor="middle" font-size="11" fill="#475569">taller than Ece</text><rect x="300" y="75" width="70" height="175" rx="6" fill="#2563eb"/><text x="335" y="67" text-anchor="middle" font-size="12" fill="#1e293b">165 cm</text><text x="335" y="268" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Zeynep</text><text x="335" y="284" text-anchor="middle" font-size="11" fill="#15803d">the tallest</text><rect x="430" y="50" width="310" height="235" rx="10" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/><text x="585" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">Superlative Rules</text><text x="450" y="104" font-size="12" fill="#854d0e">Short: the + -est → the tallest</text><text x="450" y="128" font-size="12" fill="#854d0e">Double: big → the biggest</text><text x="450" y="152" font-size="12" fill="#854d0e">-y → -iest: tidy → the tidiest</text><text x="450" y="176" font-size="12" fill="#854d0e">Long: the most organised</text><text x="450" y="200" font-size="12" fill="#854d0e">Irregular: good → the best</text><text x="450" y="224" font-size="12" fill="#854d0e">Irregular: bad → the worst</text><text x="585" y="258" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Zeynep is the tallest girl in the group.</text></svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">INTONATION OF QUESTIONS AND QUESTION TAGS</text><rect x="20" y="48" width="350" height="150" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/><text x="195" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Questions</text><text x="40" y="104" font-size="12" fill="#1e3a8a">Whose wallet is this?</text><polyline points="240,92 290,92 330,112" fill="none" stroke="#ef4444" stroke-width="3"/><text x="40" y="124" font-size="11" fill="#475569">Wh- question: falling ↘</text><text x="40" y="160" font-size="12" fill="#1e3a8a">Have you got a pen?</text><polyline points="240,160 290,160 330,140" fill="none" stroke="#22c55e" stroke-width="3"/><text x="40" y="180" font-size="11" fill="#475569">Yes/No question: rising ↗</text><rect x="390" y="48" width="350" height="150" rx="10" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/><text x="565" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">Question Tags</text><text x="410" y="104" font-size="12" fill="#9d174d">She is clever, isn\'t she?</text><polyline points="630,92 670,92 710,112" fill="none" stroke="#ef4444" stroke-width="3"/><text x="410" y="124" font-size="11" fill="#475569">Falling: I am sure (onay)</text><text x="410" y="160" font-size="12" fill="#9d174d">He has got a kit, hasn\'t he?</text><polyline points="630,160 670,160 710,140" fill="none" stroke="#22c55e" stroke-width="3"/><text x="410" y="180" font-size="11" fill="#475569">Rising: I am not sure (soru)</text><rect x="20" y="210" width="720" height="78" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/><text x="380" y="232" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">OK smarty pants, stop showing off! (Tamam bilmiş, hava atmayı bırak!)</text><text x="380" y="254" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">You\'re full of beans this morning! (Bu sabah enerji dolusun!)</text><text x="380" y="276" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Don\'t panic, just keep your cool! (Panik yapma, sakin ol!)</text></svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" fill="#f8fafc" rx="12"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="bold" fill="#1e293b">WRITING A PROFILE PARAGRAPH — 6 STEPS</text><rect x="20" y="55" width="110" height="110" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/><text x="75" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Intro</text><text x="75" y="112" text-anchor="middle" font-size="11" fill="#334155">name, age</text><text x="75" y="130" text-anchor="middle" font-size="11" fill="#334155">relation</text><text x="137" y="115" font-size="14" fill="#64748b">→</text><rect x="150" y="55" width="110" height="110" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/><text x="205" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Looks</text><text x="205" y="112" text-anchor="middle" font-size="11" fill="#334155">is tall</text><text x="205" y="130" text-anchor="middle" font-size="11" fill="#334155">has got ...</text><text x="267" y="115" font-size="14" fill="#64748b">→</text><rect x="280" y="55" width="110" height="110" rx="10" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/><text x="335" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Clothes</text><text x="335" y="112" text-anchor="middle" font-size="11" fill="#334155">usually wears</text><text x="335" y="130" text-anchor="middle" font-size="11" fill="#334155">is wearing</text><text x="397" y="115" font-size="14" fill="#64748b">→</text><rect x="410" y="55" width="110" height="110" rx="10" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/><text x="465" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">4. Character</text><text x="465" y="112" text-anchor="middle" font-size="11" fill="#334155">caring, tidy</text><text x="465" y="130" text-anchor="middle" font-size="11" fill="#334155">+ example</text><text x="527" y="115" font-size="14" fill="#64748b">→</text><rect x="540" y="55" width="100" height="110" rx="10" fill="#f5f3ff" stroke="#8b5cf6" stroke-width="1.5"/><text x="590" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#6d28d9">5. Compare</text><text x="590" y="112" text-anchor="middle" font-size="11" fill="#334155">than</text><text x="590" y="130" text-anchor="middle" font-size="11" fill="#334155">the most</text><text x="645" y="115" font-size="14" fill="#64748b">→</text><rect x="660" y="55" width="80" height="110" rx="10" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/><text x="700" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">6. Feel</text><text x="700" y="112" text-anchor="middle" font-size="11" fill="#334155">I love ...</text><text x="700" y="130" text-anchor="middle" font-size="11" fill="#334155">happily</text><rect x="20" y="182" width="720" height="104" rx="10" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/><text x="380" y="206" text-anchor="middle" font-size="14" font-weight="bold" fill="#b91c1c">Clothes in Our Culture (Kültürümüzde Giyim)</text><text x="380" y="230" text-anchor="middle" font-size="12" fill="#7f1d1d">Eid al-Fitr / Eid al-Adha: new clothes (bayramlık) · kissing elders\' hands</text><text x="380" y="252" text-anchor="middle" font-size="12" fill="#7f1d1d">23 April: folk costumes · 19 May: sports kits and trainers</text><text x="380" y="274" text-anchor="middle" font-size="12" fill="#7f1d1d">29 October Republic Day: red and white clothes, Turkish flags</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
